"use client";

import * as React from "react";
import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";

import { cn } from "@/lib/utils";
import { menuItemBase, popoverSurface, popupMotion } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

type PositionerProps = Pick<
  ContextMenuPrimitive.Positioner.Props,
  "align" | "alignOffset" | "side" | "sideOffset"
>;

/** The menu panel: the raised umber panel, at least 12rem wide, padded 0.375rem. */
const menuPanel = cn(
  popoverSurface,
  popupMotion,
  "min-w-48 max-h-(--available-height) overflow-y-auto p-1.5",
);

/** Burnished ContextMenu root: the actions a right click or long press offers. */
const ContextMenu = ContextMenuPrimitive.Root;

/** The area that opens the menu on right click or long press. */
const ContextMenuTrigger = ContextMenuPrimitive.Trigger;

/** Groups related rows, and gives a label something to name. */
const ContextMenuGroup = ContextMenuPrimitive.Group;

/** Moves a menu panel to the end of the document body. */
const ContextMenuPortal = ContextMenuPrimitive.Portal;

/** Wraps a nested menu: its sub-trigger and its sub-content. */
const ContextMenuSub = ContextMenuPrimitive.SubmenuRoot;

/** Holds a set of radio rows where only one can be chosen. */
const ContextMenuRadioGroup = ContextMenuPrimitive.RadioGroup;

/**
 * Burnished context menu: the raised umber panel with a lit top edge and a
 * 0.875rem corner, opened at the pointer and growing from that point.
 */
function ContextMenuContent({
  className,
  ...props
}: WithClassName<ContextMenuPrimitive.Popup.Props>) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner className="isolate z-50 outline-none">
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuContent.displayName = "ContextMenuContent";

/** A nested menu panel. It opens beside its row, level with the row's top. */
function ContextMenuSubContent({
  className,
  align = "start",
  alignOffset = -6,
  side = "right",
  sideOffset = 4,
  ...props
}: WithClassName<ContextMenuPrimitive.Popup.Props> & PositionerProps) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-sub-content"
          className={cn(menuPanel, className)}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}
ContextMenuSubContent.displayName = "ContextMenuSubContent";

/**
 * A menu row: 2.25rem tall with a 0.625rem corner that takes the warm accent
 * under the pointer or keyboard. The destructive variant turns the text red
 * and lights a faint red wash instead.
 */
function ContextMenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: WithClassName<ContextMenuPrimitive.Item.Props> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-variant={variant}
      className={cn(
        menuItemBase,
        "[&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground",
        variant === "destructive" &&
          "text-destructive data-[highlighted]:bg-destructive/15 data-[highlighted]:text-destructive [&_svg]:text-current",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
ContextMenuItem.displayName = "ContextMenuItem";

/** A row that opens a nested menu, with a caret at the end. */
function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.SubmenuTrigger.Props> & {
  inset?: boolean;
}) {
  return (
    <ContextMenuPrimitive.SubmenuTrigger
      data-slot="context-menu-sub-trigger"
      className={cn(
        menuItemBase,
        "data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      <ChevronRightIcon
        className="ms-auto size-4 text-muted-foreground rtl:rotate-180"
        aria-hidden="true"
      />
    </ContextMenuPrimitive.SubmenuTrigger>
  );
}
ContextMenuSubTrigger.displayName = "ContextMenuSubTrigger";

/** A row that toggles on and off. A copper tick sits at the start when on. */
function ContextMenuCheckboxItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.CheckboxItem.Props>) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center text-primary-text">
        <ContextMenuPrimitive.CheckboxItemIndicator>
          <CheckIcon className="size-4" aria-hidden="true" />
        </ContextMenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.CheckboxItem>
  );
}
ContextMenuCheckboxItem.displayName = "ContextMenuCheckboxItem";

/** One choice in a radio group. A small cream bevel dot sits at the start when chosen. */
function ContextMenuRadioItem({
  className,
  children,
  ...props
}: WithClassName<ContextMenuPrimitive.RadioItem.Props>) {
  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      className={cn(menuItemBase, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.RadioItemIndicator>
          <span className="block size-2 rounded-full bg-(image:--fill-primary) shadow-(--bevel-primary)" />
        </ContextMenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.RadioItem>
  );
}
ContextMenuRadioItem.displayName = "ContextMenuRadioItem";

/** A small muted heading over a group of rows. Use it inside a group. */
function ContextMenuLabel({
  className,
  inset,
  ...props
}: WithClassName<ContextMenuPrimitive.GroupLabel.Props> & {
  inset?: boolean;
}) {
  return (
    <ContextMenuPrimitive.GroupLabel
      data-slot="context-menu-label"
      className={cn(
        "px-2.5 py-1.5 text-xs font-semibold tracking-[0.016em] text-muted-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}
ContextMenuLabel.displayName = "ContextMenuLabel";

/** A dark hairline between groups that runs to the panel's edges. */
function ContextMenuSeparator({
  className,
  ...props
}: WithClassName<ContextMenuPrimitive.Separator.Props>) {
  return (
    <ContextMenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={cn("-mx-1.5 my-1.5 h-px bg-border", className)}
      {...props}
    />
  );
}
ContextMenuSeparator.displayName = "ContextMenuSeparator";

/** The keyboard shortcut at the end of a row, in small muted type. */
function ContextMenuShortcut({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn("ms-auto ps-4 text-xs tracking-[0.08em] text-muted-foreground", className)}
      {...props}
    />
  );
}
ContextMenuShortcut.displayName = "ContextMenuShortcut";

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuCheckboxItem,
  ContextMenuRadioItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuGroup,
  ContextMenuPortal,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuRadioGroup,
};

// Phosphor, the icon library this system pairs with, drawn inline
// so the installed component loads no icon at runtime:
// "ph:check-bold" "ph:caret-right"
// [BD-1029]
function CheckIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m232.49 80.49l-128 128a12 12 0 0 1-17 0l-56-56a12 12 0 1 1 17-17L96 183L215.51 63.51a12 12 0 0 1 17 17Z"/>
    </svg>
  );
}
function ChevronRightIcon(props: React.SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m181.66 133.66l-80 80a8 8 0 0 1-11.32-11.32L164.69 128L90.34 53.66a8 8 0 0 1 11.32-11.32l80 80a8 8 0 0 1 0 11.32"/>
    </svg>
  );
}
